<script setup>
import { ref } from 'vue';
import { MoreVertical, Clipboard, ArrowLeftRight, Copy, Images, GitMerge, Pencil, UserRoundPen, Trash2 } from 'lucide-vue-next';
import UiDialog from './UiDialog.vue';
import UiButton from './UiButton.vue';
import { duplicateProject, copyPhotos, mergeProjects, projectOwner, changeOwner, copySaid } from '../api/training.js';
const props=defineProps({project:Object,projects:Array,folders:Array});
const emit=defineEmits(['rename','move','trash','done']);
// Renaming and moving a project are its Owner's (the backend refuses anyone else; this only says so first).
const owns=()=>(props.project.rights||[]).includes('manage');
function move(){emit('move',value.value);action.value='';}
const popup=ref(null);const trigger=ref(null);const action=ref('');const value=ref('');const message=ref('');
const options=[{name:'Copy Project Id',icon:Clipboard},{name:'Move Project',icon:ArrowLeftRight,divider:true},{name:'Duplicate Project',icon:Copy},{name:'Copy Images to Project',icon:Images},{name:'Merge Projects...',icon:GitMerge},{name:'Rename Project',icon:Pencil,divider:true},{name:'Change Owner',icon:UserRoundPen},{name:'Move to Trash',icon:Trash2,divider:true}];
function toggle(){if(popup.value.matches(':popover-open'))popup.value.hidePopover();else{const rect=trigger.value.getBoundingClientRect();popup.value.style.left=`${Math.max(12,Math.min(rect.right-240,window.innerWidth-252))}px`;popup.value.style.top=`${Math.max(12,Math.min(rect.bottom+5,window.innerHeight-408))}px`;popup.value.showPopover();}}
function choose(name){popup.value.hidePopover();action.value=name;value.value=name==='Rename Project'?props.project.name:name==='Duplicate Project'?`${props.project.name} copy`:name==='Move Project'?(props.project.folder||''):'';message.value='';confirm.value='';result.value='';owner.value=null;if(name==='Change Owner')loadOwner();}
// Duplicate, Copy images, Merge and Change owner run on the backend, which decides every rule (both projects managed,
// a customer photo only where its own data-use answers let it go, a project handed only to another of its Owners).
const busy=ref(false);const confirm=ref('');const result=ref('');const owner=ref(null);
// The projects a copy or a merge may go to: other vision projects this person manages.
const targets=()=>(props.projects||[]).filter(p=>p.ref!==props.project.ref&&p.family!=='llm'&&(p.rights||[]).includes('manage'));
async function run(work){if(busy.value)return;busy.value=true;message.value='';try{await work();}catch(e){message.value=e.message;}finally{busy.value=false;}}
function duplicate(){if(!value.value.trim()){message.value='Enter a name for the copy.';return;}run(async()=>{const body=await duplicateProject(props.project.ref,value.value.trim());action.value='';emit('done',copySaid(body,body.project.name));});}
function copyInto(){const into=targets().find(p=>p.ref===value.value);if(!into){message.value='Choose a project.';return;}run(async()=>{const body=await copyPhotos(props.project.ref,into.ref);result.value=copySaid(body,into.name);emit('done',result.value);});}
function merge(){const into=targets().find(p=>p.ref===value.value);if(!into){message.value='Choose a project.';return;}run(async()=>{const body=await mergeProjects(props.project.ref,into.ref,confirm.value.trim());action.value='';emit('done',`${copySaid(body,into.name)} “${props.project.name}” is in the Trash; its Owner can restore it within 30 days.`);});}
function loadOwner(){run(async()=>{owner.value=await projectOwner(props.project.ref);value.value=owner.value.owners[0]?.id??'';});}
function handOver(){if(!value.value){message.value='Choose an Owner.';return;}run(async()=>{const body=await changeOwner(props.project.ref,value.value);action.value='';emit('done',body.said);});}
async function copyId(){try{await navigator.clipboard.writeText(props.project.id);message.value='Project ID copied.';}catch{message.value='Copy the project ID from the field above.';}}
function rename(){if(!value.value.trim()){message.value='Enter a project name.';return;}emit('rename',value.value.trim());action.value='';}
const explanations={ 'Move Project':'Choose a destination folder for this project.', 'Duplicate Project':'A new project in this workspace with this project\'s data-use answers, classes and photos. Accepted labels come along as your drafts, to check again. Customer photos come along only when this project\'s answers let them train models outside it.', 'Copy Images to Project':'Copies this project\'s photos into another project you manage; they stay here too. Accepted labels come along as your drafts there. A customer photo goes only where this project\'s data-use answers let it go.', 'Merge Projects...':'Copies every photo into the project you choose, then moves this project to the Trash, where its Owner can restore it within 30 days. When any photo cannot be copied, nothing is moved to the Trash.', 'Change Owner':'Hand this project to another of its Owners: it is then kept under their account. You stay an Owner.' };
</script>
<template>
  <button ref="trigger" class="project-more icon-button" :aria-label="`Options for ${project.name}`" aria-haspopup="true" @click.stop="toggle"><MoreVertical :size="18"/></button>
  <div ref="popup" popover="auto" class="project-options" :aria-label="`Actions for ${project.name}`">
    <button v-for="item in options" :key="item.name" :class="{separator:item.divider,danger:item.name==='Move to Trash'}" @click="choose(item.name)"><component :is="item.icon" :size="16"/><span>{{item.name}}</span></button>
  </div>
  <UiDialog :open="!!action" :title="action" @close="action=''">
    <p class="dialog-description">{{project.name}}</p>
    <template v-if="action==='Copy Project Id'"><label class="field-label">Project ID<input class="text-input" :value="project.id" readonly></label><div class="dialog-actions"><UiButton @click="copyId">Copy ID</UiButton></div></template>
    <template v-else-if="action==='Rename Project'"><label class="field-label">Project name<input v-model="value" class="text-input" maxlength="80" @keydown.enter="rename"></label><p v-if="!owns()" class="dialog-description">Only the project's Owner can rename it.</p><div class="dialog-actions"><UiButton @click="action=''">Cancel</UiButton><UiButton variant="primary" :disabled="!owns()" @click="rename">Rename Project</UiButton></div></template>
    <template v-else-if="action==='Move Project'"><p class="dialog-description">{{explanations[action]}}</p><label class="field-label">Destination folder<select v-model="value" class="text-input" :disabled="!owns()"><option value="">Workspace root</option><option v-for="folder in folders" :key="folder">{{folder}}</option></select></label><p v-if="!owns()" class="dialog-description">Only the project's Owner can move it.</p><div class="dialog-actions"><UiButton @click="action=''">Cancel</UiButton><UiButton variant="primary" :disabled="!owns()" @click="move">Move Project</UiButton></div></template>
    <template v-else-if="action==='Move to Trash'"><p class="dialog-description">The project leaves every list at once and its apps can no longer send to it. Nothing is deleted now: its Owner restores it from Workspace Settings → Trash within 30 days. After that it is deleted for good, with its photos, labels and files.</p><p v-if="!owns()" class="dialog-description">Only the project's Owner can move it to the Trash.</p><div class="dialog-actions"><UiButton @click="action=''">Cancel</UiButton><UiButton variant="primary" class="trash-fill" :disabled="!owns()" @click="emit('trash');action=''">Move to Trash</UiButton></div></template>
    <template v-else-if="action==='Duplicate Project'"><p class="dialog-description">{{explanations[action]}}</p><label class="field-label">New project name<input v-model="value" class="text-input" maxlength="120" @keydown.enter="duplicate"></label><p v-if="!owns()" class="dialog-description">Only an Owner of the project can duplicate it.</p><div class="dialog-actions"><UiButton @click="action=''">Cancel</UiButton><UiButton variant="primary" :disabled="!owns()||busy||!value.trim()" @click="duplicate">{{ busy ? 'Duplicating…' : 'Duplicate' }}</UiButton></div></template>
    <template v-else-if="action==='Copy Images to Project'"><p class="dialog-description">{{explanations[action]}}</p><label class="field-label">Copy into<select v-model="value" class="text-input" :disabled="!owns()"><option value="">Choose a project</option><option v-for="other in targets()" :key="other.ref" :value="other.ref">{{other.name}}</option></select></label><p v-if="!targets().length" class="dialog-description">You manage no other vision project in this workspace.</p><p v-if="result" role="status" class="dialog-description">{{ result }}</p><div class="dialog-actions"><UiButton @click="action=''">{{ result ? 'Close' : 'Cancel' }}</UiButton><UiButton variant="primary" :disabled="!owns()||busy||!value" @click="copyInto">{{ busy ? 'Copying…' : 'Copy photos' }}</UiButton></div></template>
    <template v-else-if="action==='Merge Projects...'"><p class="dialog-description">{{explanations[action]}}</p><label class="field-label">Merge into<select v-model="value" class="text-input" :disabled="!owns()"><option value="">Choose a project</option><option v-for="other in targets()" :key="other.ref" :value="other.ref">{{other.name}}</option></select></label><label class="field-label">Type “{{ project.name }}” to merge it<input v-model="confirm" class="text-input" maxlength="120" autocomplete="off"></label><div class="dialog-actions"><UiButton @click="action=''">Cancel</UiButton><UiButton variant="primary" class="trash-fill" :disabled="!owns()||busy||!value||confirm.trim()!==project.name" @click="merge">{{ busy ? 'Merging…' : 'Merge' }}</UiButton></div></template>
    <template v-else-if="action==='Change Owner'"><p class="dialog-description">{{explanations[action]}}</p><p v-if="!owner&&busy" class="dialog-description">Loading…</p><template v-else-if="owner"><p class="dialog-description">Kept under {{ owner.owner }} now.</p><p v-if="!owner.you_own" class="dialog-description">Only {{ owner.owner }} can hand it over.</p><p v-else-if="!owner.owners.length" class="dialog-description">Nobody else is an Owner of this project yet. Make the person an Owner in Team Members first.</p><label v-else class="field-label">Hand it to<select v-model="value" class="text-input"><option v-for="o in owner.owners" :key="o.id" :value="o.id">{{ o.name }}</option></select></label></template><div class="dialog-actions"><UiButton @click="action=''">Cancel</UiButton><UiButton variant="primary" :disabled="busy||!owner?.you_own||!owner?.owners.length" @click="handOver">Hand over</UiButton></div></template>
    <p v-if="message" role="status" class="dialog-description">{{message}}</p>
  </UiDialog>
</template>
<style scoped>
.trash-fill{background:#d92d20;border-color:#d92d20}
.project-more{position:absolute;right:10px;top:10px;background:#fffffff0;border:1px solid var(--aadml-soft);z-index:2;width:30px;height:30px}.project-options{position:fixed;inset:auto;margin:0;width:240px;padding:5px;border:1px solid #dfe1e8;border-radius:10px;background:white;color:#536074;box-shadow:0 5px 16px #18223424;z-index:100}.project-options button{width:100%;display:flex;align-items:center;gap:12px;padding:11px 12px;border:0;background:white;text-align:left;font-size:14px;color:inherit}.project-options button:hover,.project-options button:focus-visible{background:var(--aadml-tint);color:var(--aadml-primary)}.project-options svg{color:#99a1b0}.project-options .separator{border-top:1px solid #e4e5eb;margin-top:3px;padding-top:14px}.project-options .danger,.project-options .danger svg{color:#e73d7b}
</style>
